assert len(REAL_CASES) == 15
for case in REAL_CASES:
    gold = case["gold"]
    variants = [{"text": case["text"], "answer": gold},
                {"text": case["text"], "answer": "999999999999999999999"},
                {"text": case["text"] + "\n#### 999999999999999999999", "answer": gold}]
    scores = runpy.run_path(str(verifier), init_globals={"SCORE_INPUT": variants})["SCORE_OUTPUT"]
    assert scores[0]["correct"], (case["id"], case["sample_index"], scores[0])
    assert scores[1]["status"] == "incorrect" and scores[1]["extracted"] == scores[0]["extracted"], case["id"]
    assert scores[2]["status"] == "ambiguous" and not scores[2]["correct"], case["id"]
    checks += 3

long_records = [
    {"text": "Ordinary reasoning with no explicit response marker. " * 40000 + "\n#### 17", "answer": "17"},
    {"text": "#### 17\n" * 5000, "answer": "17"},
    {"text": "<answer>" * 10000 + "\n#### 17", "answer": "17"},
    {"text": "<think>" * 10000 + "\n#### 17", "answer": "17"},
    {"text": r"\boxed{" * 10000 + "17", "answer": "17"},
    {"text": "<think>" + "Use #### <answer> as a placeholder. " * 40000 + "</think>\n#### 17", "answer": "17"},
]
started = time.perf_counter()
long_scores = runpy.run_path(str(verifier), init_globals={"SCORE_INPUT": long_records})["SCORE_OUTPUT"]
assert [score["status"] for score in long_scores] == ["correct", "correct", "extraction_failed", "extraction_failed", "extraction_failed", "correct"]
long_elapsed = time.perf_counter() - started
checks += len(long_records)

flag_scores = runpy.run_path(str(verifier), init_globals={"SCORE_INPUT": [
    {"text": "#### 17", "answer": "17", "truncated": True},
    {"text": "#### 17", "answer": "17", "infrastructure_error": "fixture"}]})["SCORE_OUTPUT"]
assert flag_scores[0]["correct"] and flag_scores[0]["truncated"]
assert flag_scores[1]["status"] == "infrastructure_error" and not flag_scores[1]["correct"]
checks += 2

with tempfile.TemporaryDirectory(prefix="verifier v2 CLI ") as temporary:
    input_path = Path(temporary) / "input.jsonl"
    output_path = Path(temporary) / "output.jsonl"
    input_path.write_text(json.dumps({"text": "Final numerical answer: ₣17", "answer": "17"}) + "\n")
    result = subprocess.run([sys.executable, "-S", str(verifier), "--input", str(input_path), "--output", str(output_path)], capture_output=True, text=True)
    assert result.returncode == 0, result.stderr
    assert json.loads(output_path.read_text())["correct"]
    checks += 1
print(f"✅ [VERIFIER V2] {checks} independent/real-fixture/CLI checks; six long-output checks in {long_elapsed:.2f}s; no model or network calls")
